["idp","nl -ba store/idp.go; nl -ba internal/idp/idp.go; nl -ba internal/idp/oauth2/oauth2.go"],
["delete","nl -ba store/user_delete.go; nl -ba store/reaction.go; nl -ba store/db/sqlite/sqlite.go | head -100; rg -n \"reaction|FOREIGN KEY|user.*delete\" store/migration store/db --glob '*.sql' --glob '*.go'"],
["image","rg -n \"profile.*image|Image|Avatar|GetUser\" server/router/api/v1 --glob '*.go' | head -180; nl -ba server/router/api/v1/attachment_service_image.go"],
["md","nl -ba internal/markdown/markdown.go; rg -n \"markdown.Service|New.*Markdown|MarkdownService\" --glob '*.go'"],
["memo","nl -ba store/db/db.go; nl -ba store/db/sqlite/memo.go | head -50; nl -ba store/memo.go | sed -n '1,180p'; rg -n \"RebuildMemoPayload|Payload\" server/router/api/v1 --glob '*.go'"],
["vis","rg -n \"Visibility|visibility|Can.*Memo|Memo.*Access|IsMemo\" server/router/api/v1 --glob '*.go' | head -240"],
["reality","rg -n \"redis|cache|TTL|rate.?limit|graphql|Rabbit|NATS|broker|cron|cleanup\" . --glob '!*.sum' | head -260"]
];
const rs = await Promise.all(qs.map(async ([n,cmd])=>[n,(await tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:12000})).output]));
for (const [n,o] of rs) { text(`===${n}===\n${o}`); }

