const cmds=[
"nl -ba store/db/db.go; rg -n \"func \\(.*\\) DeleteUser|DeleteUser\\(\" store/db --glob '*.go' store --glob '*.go' | head -100",
"rg -n \"reaction\" store/db/{sqlite,postgres,mysql} store/migration --glob '*.go' --glob '*.sql'",
"rg -n \"Profile|profile.*image|image.*profile|GetUser.*Image|GetUser.*Avatar|avatar\" server/router/api/v1 store --glob '*.go'",
"nl -ba internal/markdown/markdown.go; rg -n \"markdown\\.New|NewMarkdown|MarkdownService|markdown.Service\" --glob '*.go'",
"rg -n \"RebuildMemoPayload|Payload\" server/router/api/v1/memo_service.go server/router/api/v1/memo_update_helpers.go server/router/api/v1/memo_service_query.go",
"rg -n \"visibility|Visibility\" server/router/api/v1 --glob '*.go' | grep -v _test.go",
"rg -n \"func \\(.*\\) Close|\\.Close\\(\" store server --glob '*.go' | grep -v _test.go"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:8000})));
for(let i=0;i<rs.length;i++) text(`===${i+1}===\n${rs[i].output}`);

